from pathlib import Path
import json,re

# v0.25 Storybook Meadow: pastoral depth over diagrammatic decoration.

def subf(s,name,next_name,new):
    a=s.find('function '+name+'(')
    b=s.find('\nfunction '+next_name+'(',a)
    if a<0 or b<0: raise SystemExit('replace failed '+name)
    return s[:a]+new+s[b:]

p=Path('package.json');j=json.loads(p.read_text());j['version']='0.25.0';p.write_text(json.dumps(j,indent=2)+'\n')
p=Path('index.html');s=p.read_text();s=re.sub(r'<title>.*?</title>','<title>Stretchicorn v0.25.0 - STORYBOOK MEADOW</title>',s);p.write_text(s)

