world="""function worldArt(l){X.save();let b=wave<5?0:wave<9?1:wave<12?2:3,h=H*.72,z=cl((l-.18)/.82,0,1),q=Math.sin(t*.35),hc=['#172719','#241811','#172727','#17101f'][b],gc=['#101b12','#21140d','#102020','#120b18'][b];X.globalAlpha=.26;oval(170,h+30,350,130,hc);oval(720,h+45,430,155,hc);X.globalAlpha=.12+z*.18;for(let i=0;i<6;i++){ink(RC[i],3.5);X.beginPath();X.arc(W*.7,h+58,235+i*6,Math.PI*1.08,Math.PI*1.92);X.stroke()}X.globalAlpha=.45;X.fillStyle=gc;X.fillRect(0,h,W,H-h);X.globalAlpha=.25;X.fillStyle='#d8e0d0';X.fillRect(0,h-2,W,3);X.globalAlpha=1;for(let i=0;i<18;i++){let x=(i*67+wave*29)%W,y=h+34+(i%4)*18,s=.7+(i%3)*.18,c=b==3?'#3d3150':b==2?'#384d45':'#31452f';ink(c,2*s);for(let k=-1;k<2;k++){X.beginPath();X.moveTo(x,y);X.quadraticCurveTo(x+k*5+q*2,y-10*s,x+k*8+q*4,y-23*s);X.stroke()}if(i%4==0){let f=z>.35?RC[(i+wave)%6]:'#6e725e';oval(x+q*2,y-25*s,3*s,2*s,f)}}if(b==0){X.globalAlpha=.72;ink('#544d32',5);for(let i=0;i<5;i++){let x=70+i*155,y=h+12+(i&1)*8;X.beginPath();X.moveTo(x,y+38);X.lineTo(x+5,y-32);X.stroke();if(i<4){ink('#403923',4);X.beginPath();X.moveTo(x+5,y-10);X.lineTo(x+150,y-22);X.stroke();ink('#544d32',5)}}let x=800,y=h-88;ink('#2f372b',7);X.beginPath();X.moveTo(x,y+92);X.lineTo(x+9,y);X.stroke();oval(x+9,y,8,8,'#30372d');ink('#5b6254',3);for(let i=0;i<4;i++){let a=t*.05+i*T/4;X.beginPath();X.moveTo(x+9,y);X.lineTo(x+9+Math.cos(a)*42,y+Math.sin(a)*42);X.stroke()}ink('#252d27',2);for(let i=0;i<2;i++){let x=155+i*90,y=155+i*22;X.beginPath();X.arc(x,y,13,.15,1.25);X.arc(x+24,y,13,1.9,3);X.stroke()}}else if(b==1){X.globalAlpha=.72;X.fillStyle='#1b0f0b';X.fillRect(65,h-115,130,115);X.beginPath();X.moveTo(45,h-115);X.lineTo(130,h-175);X.lineTo(215,h-115);X.fill();X.fillStyle='#2e1a11';X.fillRect(112,h-72,34,72);let x=760,y=h-120;ink('#312316',7);X.beginPath();X.moveTo(x,y+120);X.lineTo(x,y);X.moveTo(x-48,y+22);X.lineTo(x+50,y+22);X.stroke();X.fillStyle='#25160f';X.beginPath();X.moveTo(x-27,y-5);X.lineTo(x+28,y-5);X.lineTo(x+16,y-20);X.lineTo(x-17,y-20);X.fill();ink('#6b5130',3);for(let i=0;i<6;i++){let sx=280+i*72,sy=h+8+(i&1)*10;X.beginPath();X.moveTo(sx,sy);X.lineTo(sx+q*2,sy-45);X.stroke();oval(sx+q*2,sy-49,9,7,i%2?'#574126':'#44351f')}}else if(b==2){X.globalAlpha=.55;for(let i=0;i<4;i++){let x=120+i*235,y=h+44+(i&1)*22;oval(x,y,88,12,'#203336');X.globalAlpha=.15+z*.18;oval(x-8,y-3,55,3,RC[(i+3)%6]);X.globalAlpha=.55}let x=760,y=h-56;ink('#3d5048',7);X.beginPath();X.arc(x,y,63,0,T);X.stroke();for(let i=0;i<6;i++){let a=i*T/6+t*.025;X.beginPath();X.moveTo(x,y);X.lineTo(x+Math.cos(a)*63,y+Math.sin(a)*63);X.stroke()}ink('#2b4038',3);for(let i=0;i<8;i++){let x=45+i*86,y=h+25+(i%3)*9;for(let k=-1;k<2;k++){X.beginPath();X.moveTo(x,y);X.quadraticCurveTo(x+k*4,y-22,x+k*8+q*2,y-57);X.stroke()}}}else{X.globalAlpha=.78;X.fillStyle='#120d18';X.beginPath();X.moveTo(80,H);X.quadraticCurveTo(135,h-150,190,h-245);X.quadraticCurveTo(240,h-115,315,H);X.fill();ink('#45344d',7);for(let i=0;i<4;i++){let y=150+i*82;X.beginPath();X.moveTo(i&1?0:W,y);X.quadraticCurveTo(W/2+Math.sin(t*.12+i)*75,y-75,W*.57,h+8);X.stroke()}for(let i=0;i<7;i++){let x=365+i*78,y=h+18+(i%3)*13,c=z>.25?RC[(i+2)%6]:'#5d5362';X.fillStyle=c;X.beginPath();X.moveTo(x,y-26);X.lineTo(x+7,y-12);X.lineTo(x,y);X.lineTo(x-7,y-12);X.fill()}}if(z>.2){X.globalAlpha=.35*z;for(let i=0;i<6;i++){let x=(130+i*157+Math.sin(t*.6+i)*18)%W,y=h-50-(i%3)*35+Math.sin(t*1.2+i)*8;oval(x,y,2,2,RC[(i+wave)%6])}}X.restore()}"""

boss="""function bossArt(l){if(!queen)return;X.save();let z=.13+l*.16,cx=W/2,cy=H*.55;X.globalAlpha=z;if(queen==3){ink('#120b16',18);for(let i=0;i<3;i++){let y=120+i*145;X.beginPath();X.moveTo(i&1?0:W,y);X.quadraticCurveTo(cx+(i-1)*95,y-80,cx+(i-1)*35,H*.78);X.stroke()}X.globalAlpha=z*.65;for(let i=0;i<3;i++){ink(RC[(i+4)%6],2);X.beginPath();X.moveTo(i&1?0:W,128+i*145);X.quadraticCurveTo(cx+(i-1)*95,48+i*145,cx+(i-1)*35,H*.78);X.stroke()}}else if(wave==5){X.globalAlpha=z*.55;oval(cx,cy+25,185,155,'#2a160d');X.globalAlpha=z;ink('#694726',12);X.beginPath();X.moveTo(cx,cy+150);X.lineTo(cx,cy-95);X.moveTo(cx-105,cy-45);X.lineTo(cx+110,cy-45);X.stroke();X.fillStyle='#3b2416';X.beginPath();X.moveTo(cx-58,cy-108);X.lineTo(cx+62,cy-108);X.lineTo(cx+38,cy-142);X.lineTo(cx-30,cy-142);X.fill();ink('#8a6734',4);for(let i=0;i<5;i++){let x=cx-210+i*105;X.beginPath();X.moveTo(x,cy+150);X.quadraticCurveTo(x+12,cy+50,x+Math.sin(i)*18,cy-18);X.stroke()}}else if(wave==9){let x=cx+135,y=cy+55;ink('#4a5c54',10);X.beginPath();X.arc(x,y,105,0,T);X.stroke();for(let i=0;i<7;i++){let a=i*T/7+t*.018;X.beginPath();X.moveTo(x,y);X.lineTo(x+Math.cos(a)*105,y+Math.sin(a)*105);X.stroke()}X.globalAlpha=z*.7;oval(cx-170,cy+135,165,18,'#243638');ink('#637970',4);X.beginPath();X.moveTo(70,cy+120);X.quadraticCurveTo(cx,cy+75,W-55,cy+128);X.stroke()}else if(wave==13){ink('#27162e',18);for(let i=0;i<4;i++){let x=i<2?0:W,y=155+(i%2)*175;X.beginPath();X.moveTo(x,y);X.bezierCurveTo(cx+(i-1.5)*180,70+i*30,cx+(i-1.5)*70,cy-120,cx,cy+30);X.stroke()}X.globalAlpha=z*.8;oval(cx,cy+20,105,80,'#07040a');ink('#6e4a72',4);X.beginPath();X.arc(cx,cy+20,125,0,T);X.stroke()}X.restore()}"""

